        cross = kq + 30.0 * (qt @ st.T)
        ridge = 0.0001
    factor = cho_factor(gram + ridge * np.eye(len(gram)))
    return {'y_hat': cross @ cho_solve(factor, p['y_centered']) + p['y_mean']}
